package assignment.piece;

import assignment.piece.Rule;
import assignment.protocol.Game;
import assignment.protocol.Move;
import assignment.protocol.Piece;
import assignment.protocol.Place;

/**
 * The rule that requires capturing piece is not allowed within the first certain number of moves.
 */
public class FirstNMovesProtectionRule implements Rule {
    /**
     * The number of moves within which capturing piece is not allowed.
     */
    private final int numProtectedMoves;

    public FirstNMovesProtectionRule(int numProtectedMoves) {
        this.numProtectedMoves = numProtectedMoves;
    }

    @Override
    public boolean validate(Game game, Move move) {
        // If we're past the protected moves, any move is valid
        if (game.getNumMoves() >= numProtectedMoves) {
            return true;
        }

        // During protected moves, check if the destination has an opponent's piece
        Place destination = move.getDestination();
        Piece destinationPiece = game.getPiece(destination);

        // If there's no piece at the destination, the move is valid (not a capture)
        if (destinationPiece == null) {
            return true;
        }

        // If there's a piece at the destination, check if it belongs to the opponent
        // If it does, this would be a capture, which is not allowed during protected moves
        Piece sourcePiece = game.getPiece(move.getSource());
        if (sourcePiece != null && destinationPiece.getPlayer() != sourcePiece.getPlayer()) {
            // This is a capture move during protected period - not allowed
            return false;
        }

        // Otherwise, the move is valid
        return true;
    }

    @Override
    public String getDescription() {
        return "Capturing piece in the first " + this.numProtectedMoves + " moves are not allowed";
    }
}
```

The implementation logic:
1. First checks if the game has already passed the protected number of moves. If so, any move is valid.
2. During the protected period, it checks if the destination square contains an opponent's piece.
3. If the destination is empty, the move is valid (not a capture).
4. If the destination contains an opponent's piece, it's a capture move which is not allowed during the protected period, so it returns false.
5. Otherwise, the move is valid.

