```java
package assignment.piece;

import assignment.piece.Rule;
import assignment.protocol.Configuration;
import assignment.protocol.Game;
import assignment.protocol.Move;
import assignment.protocol.Place;

/**
 * Global rule that requires the source and destination should be inside the board boundary.
 */
public class OutOfBoundaryRule implements Rule {
    @Override
    public boolean validate(Game game, Move move) {
        Configuration config = game.getConfiguration();
        int boardSize = config.getSize();

        Place source = move.getSource();
        Place destination = move.getDestination();

        // Check if source is within bounds
        if (source.x() < 0 || source.x() >= boardSize || 
            source.y() < 0 || source.y() >= boardSize) {
            return false;
        }

        // Check if destination is within bounds
        if (destination.x() < 0 || destination.x() >= boardSize || 
            destination.y() < 0 || destination.y() >= boardSize) {
            return false;
        }

        return true;
    }

    @Override
    public String getDescription() {
        return "place is out of boundary of gameboard";
    }
}
```

The `validate` method:
1. Gets the board size from the game's configuration
2. Retrieves the source and destination places from the move
3. Checks if both x and y coordinates of the source are within bounds (0 to boardSize-1)
4. Checks if both x and y coordinates of the destination are within bounds (0 to boardSize-1)
